	lone := &DecodeError{Offset: start, Message: "a lone surrogate"}
	high, err := r.hex4()
	if err != nil {
		return 0, err
	}
	switch {
	case high >= 0xd800 && high <= 0xdbff:
		if !strings.HasPrefix(string(r.text[r.at:]), `\u`) {
			return 0, lone
		}
		r.at += 2
		low, err := r.hex4()
		if err != nil {
			return 0, err
		}
		if low < 0xdc00 || low > 0xdfff {
			return 0, lone
		}
		return 0x10000 + (high-0xd800)<<10 + (low - 0xdc00), nil
	case high >= 0xdc00 && high <= 0xdfff:
		return 0, lone
	}
	return high, nil
