func readVersion(r *jsonReader) (Version, error) {
	r.space()
	start := r.at
	text, err := readString(r)
	if err != nil {
		return Version{}, err
	}
	part := func(s string) (uint32, bool) {
		if s == "" || strings.Trim(s, "0123456789") != "" || (s != "0" && s[0] == '0') {
			return 0, false
		}
		v, err := strconv.ParseUint(s, 10, 32)
		return uint32(v), err == nil
	}
	major, minor, found := strings.Cut(text, ".")
	if found {
		ma, ok1 := part(major)
		mi, ok2 := part(minor)
		if ok1 && ok2 {
			return Version{Major: ma, Minor: mi}, nil
		}
	}
	return Version{}, &DecodeError{Offset: start, Message: fmt.Sprintf("%q is not a version, \"MAJOR.MINOR\"", text)}
}

